// Word-by-word karaoke lyric video. Words + timings come from words.js (generated by align.py from segments.json).
'use strict';
const DUR = 18.089;
const $ = id => document.getElementById(id);
const C = (x, a = 0, b = 1) => Math.min(b, Math.max(a, x));
const P = (t, a, b) => C((t - a) / (b - a));
const L = (a, b, p) => a + (b - a) * p;
const eo3 = p => 1 - Math.pow(1 - p, 3);
const back = (p, s = 1.70158) => 1 + (s + 1) * Math.pow(p - 1, 3) + s * Math.pow(p - 1, 2);
const st = (el, o) => Object.assign(el.style, o);
function rng(seed) { return () => { seed |= 0; seed = seed + 0x6D2B79F5 | 0; let t = Math.imul(seed ^ seed >>> 15, 1 | seed); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }; }

const BEATS = []; for (let b = .47; b < DUR; b += .5) BEATS.push(b);
const lastBeat = T => { let b = -9; for (const x of BEATS) if (x <= T) b = x; return b; };
const COLORS = ['#ff2d95', '#ffd60a', '#ff7a00'];               // fuchsia / yellow / orange
const norm = w => w.toLowerCase().replace(/[(),.?']/g, '');
// punchlines: bigger + impact
const KEY = { baddies: 0, bélgica: '🇧🇪', holanda: '🇳🇱', frança: '🇫🇷', españa: '🇪🇸', keke: '🇨🇩', congolaise: 0, yasmina: '🇲🇦', marocaine: 0, beyza: '🇹🇷', turkiye: 0, malaisien: '🇲🇾', allemaal: 0 };
const W = window.WORDS.map((w, i) => ({ ...w, i, key: norm(w.w) in KEY, flag: KEY[norm(w.w)] || null, col: COLORS[i % 3] }));
W.forEach((w, i) => { const nx = W.slice(i + 1).find(x => x.seg !== w.seg || true); w.end = nx ? nx.t : DUR; });
// group = main segment (ad-libs ride along as stickers)
const SEGS = [...new Set(W.filter(w => !w.ad || w.seg === 2).map(w => w.seg))];
const segStart = s => W.find(w => w.seg === s).t;

const gctx = $('grain').getContext('2d'), gimg = gctx.createImageData(360, 640);
function drawGrain(f) { const r = rng(f * 9973 + 1), d = gimg.data; for (let i = 0; i < d.length; i += 4) { const v = r() * 255; d[i] = d[i + 1] = d[i + 2] = v; d[i + 3] = 255; } gctx.putImageData(gimg, 0, 0); }
const fx = $('fx').getContext('2d');
function burst(x, y, d, seed, big) {
  const r = rng(seed), p = P(d, 0, .45); if (p <= 0 || p >= 1) return;
  fx.strokeStyle = `rgba(255,255,255,${(1 - p) * .9})`; fx.lineWidth = (big ? 18 : 10) * (1 - p) + 1;
  fx.beginPath(); fx.arc(x, y, eo3(p) * (big ? 640 : 420), 0, Math.PI * 2); fx.stroke();
  for (let i = 0; i < (big ? 28 : 16); i++) {
    const a = r() * Math.PI * 2, v = (260 + r() * 520) * (big ? 1.3 : 1), dist = eo3(p) * v;
    fx.fillStyle = COLORS[i % 3]; fx.globalAlpha = 1 - p;
    const s = (10 + r() * 16) * (1 - p);
    fx.save(); fx.translate(x + Math.cos(a) * dist, y + Math.sin(a) * dist); fx.rotate(a + p * 4); fx.fillRect(-s / 2, -s / 2, s, s * .6); fx.restore();
  }
  fx.globalAlpha = 1;
}

function fitSize(word, base, peak) { return Math.min(base, 1000 / peak / Math.max(1, word.length * .68)); }

function render(T) {
  const frame = Math.round(T * 30);
  fx.clearRect(0, 0, 1080, 1920);
  const lb = lastBeat(T), bp = Math.exp(-(T - lb) / .12);
  // the last word that has been sung drives colour/impact
  let cur = null; for (const w of W) if (T >= w.t - .04) cur = w;
  const hue = cur ? cur.col : COLORS[0];

  // background: warm gradient, moving blobs, pulsing rays
  $('stage').style.background = `radial-gradient(ellipse at 50% 60%, #4a0a3c 0%, #1a0420 70%)`;
  st($('b1'), { background: '#ff2d95', left: 40 + Math.sin(T * .7) * 180 + 'px', top: 200 + Math.cos(T * .5) * 200 + 'px', opacity: .55 + .25 * bp });
  st($('b2'), { background: '#ff7a00', left: 300 + Math.cos(T * .6) * 200 + 'px', top: 1000 + Math.sin(T * .8) * 180 + 'px', opacity: .5 + .2 * bp });
  st($('b3'), { background: '#ffd60a', left: -200 + Math.sin(T * .9 + 1) * 160 + 'px', top: 1300 + Math.cos(T * .6) * 160 + 'px', opacity: .35 + .2 * bp });
  st($('rays'), { transform: `rotate(${T * 14}deg) scale(${1 + .06 * bp})`, opacity: .7 + .3 * bp });

  // current chunk = segment of the current word (ad-libs go to stickers)
  let segIdx = 0; SEGS.forEach((s, i) => { if (T >= segStart(s) - .04) segIdx = i; });
  const seg = SEGS[segIdx], words = W.filter(w => w.seg === seg);
  const isAdLine = seg === 2;
  const nextStart = segIdx + 1 < SEGS.length ? segStart(SEGS[segIdx + 1]) : 99;
  const out = P(T, nextStart - .12, nextStart);
  let h = '';
  for (const w of words) {
    const base = isAdLine ? 110 : w.key ? 190 : 140, fs = fitSize(w.w, base, w.key ? 1.18 : 1.08);
    if (T < w.t - .04) { continue; }                                   // word by word: not shown before it's sung
    const d = T - (w.t - .04), pop = back(P(d, 0, .22), w.key ? 3.2 : 2.2);
    const s = Math.min(w.key ? 1.18 : 1.08, (w.key ? .3 : .55) + (w.key ? .7 : .45) * pop + (w.key ? .15 * Math.exp(-Math.max(0, d - .22) / .12) : 0));
    // karaoke: colour sweeps across the word while it is being sung
    const k = eo3(P(T, w.t, w.t + Math.min(.32, Math.max(.12, w.end - w.t)))) * 100;
    const fill = `background:linear-gradient(90deg,${w.col} ${k}%,#ffffff ${k}%);-webkit-background-clip:text;background-clip:text;color:transparent`;
    const rot = w.key ? (w.i % 2 ? -4 : 4) * (1 - P(d, .15, .4)) : 0;
    h += `<span class="wd" style="font-size:${fs}px;--sw:${fs * .11}px;transform:translateY(${-out * 80}px) scale(${s * (1 - out * .3)}) rotate(${rot}deg);opacity:${1 - out};filter:drop-shadow(0 ${fs * .06}px 0 rgba(0,0,0,.55))"><span class="s">${w.w}</span><span class="f" style="${fill}">${w.w}</span></span>`;
  }
  $('chunk').innerHTML = h;

  // stickers: ad-libs "(ey)" etc. + flags on key words
  let sk = '';
  for (const w of W) {
    const d = T - w.t;
    if (w.ad && w.seg !== 2 && d >= 0 && d < .7) {
      const p = back(P(d, 0, .16), 3), o = 1 - P(d, .55, .7), r = rng(w.i * 7)();
      sk += `<div class="stk" style="left:${640 + r * 160}px;top:${880 - r * 60}px;font-size:110px;color:#ffd60a;-webkit-text-stroke:12px #000;paint-order:stroke fill;transform:translate(-50%,-50%) rotate(${-12 + r * 10}deg) scale(${p});opacity:${o};filter:drop-shadow(0 8px 0 rgba(0,0,0,.5))">${w.w}</div>`;
    }
    if (w.flag && d >= 0 && d < 1.6) {
      const p = back(P(d, .02, .2), 3), o = 1 - P(d, 1.3, 1.6);
      sk += `<div class="stk" style="left:540px;top:${860}px;font-size:150px;transform:translate(-50%,-50%) rotate(${(w.i % 2 ? 8 : -8)}deg) scale(${p});opacity:${o};filter:drop-shadow(0 10px 18px rgba(0,0,0,.45))">${w.flag}</div>`;
    }
  }
  $('stickers').innerHTML = sk;

  // impact: key words shake + flash + burst; strong hook in the first 2 s
  let shake = 0, flash = 0, zoom = 1 + .02 * bp;
  for (const w of W) {
    const d = T - w.t; if (d < 0 || d > .5) continue;
    if (w.key) { shake = Math.max(shake, 22 * Math.exp(-d / .08)); flash = Math.max(flash, .35 * Math.exp(-d / .05)); zoom += .05 * Math.exp(-d / .12); burst(540, 1150, d, w.i * 31, true); }
    else if (T < 2.4) { shake = Math.max(shake, 12 * Math.exp(-d / .06)); burst(540, 1150, d, w.i * 31, false); }
  }
  if (T < .25) { flash = Math.max(flash, 1 - P(T, 0, .25)); zoom += .25 * (1 - eo3(P(T, 0, .35))); }
  const r = rng(frame * 13 + 7);
  st($('cam'), { transform: `translate(${(r() - .5) * shake}px,${(r() - .5) * shake}px) scale(${zoom})` });
  $('flash').style.opacity = C(flash);
  st($('tag'), { opacity: P(T, .3, .6), transform: `translateX(-50%) scale(${.8 + .2 * back(P(T, .3, .6), 2)})` });
  drawGrain(frame);
}
window.render = render;
window.DUR = DUR;
window.ready = document.fonts.ready;
